
CREATE DATABASE restaurant_projects;
USE restaurant_projects;
SHOW DATABASES;

select * from restaurants;
select * from orders;
select * from customers;

-- 1.  Display all completed orders along with customer name and restaurant name. 
SELECT 
o.order_id, c.customer_name,r.restaurant_name
FROM 
orders AS o 
INNER JOIN
customers AS c
ON o.customer_id = c.customer_id 
INNER JOIN
 restaurants AS r ON o.restaurant_id = r.restaurant_id
WHERE 
o.order_status = 'Completed';

-- 2.  Find the total revenue generated by each restaurant. 
SELECT
r.restaurant_name,
SUM(o.order_amount) AS total_revenue
FROM restaurants AS r
INNER JOIN orders AS o
ON r.restaurant_id = o.restaurant_id
GROUP BY r.restaurant_name
ORDER BY total_revenue DESC;

-- 3. Show the total number of orders placed by each customer. 
SELECT
c.customer_id,
c.customer_name,
COUNT(o.order_id) AS total_orders
FROM customers AS c
LEFT JOIN orders AS o
ON c.customer_id = o.customer_id
GROUP BY
c.customer_id,
c.customer_name
ORDER BY total_orders DESC;

-- 4.  Find the average order amount for each city. 
SELECT
c.city,
ROUND(AVG(o.order_amount), 2) AS average_order_amount
FROM customers AS c
INNER JOIN orders AS o
ON c.customer_id = o.customer_id
GROUP BY c.city
ORDER BY average_order_amount DESC;

-- 5.  Categorize orders as Low, Medium, and High based on order amount.
SELECT
order_id,
order_amount,
CASE
WHEN order_amount < 500 THEN 'Low'
WHEN order_amount <= 1000 THEN 'Medium'
ELSE 'High'
END AS order_category
FROM orders
ORDER BY order_amount DESC;

-- 6.  Display restaurants whose average order value is greater than the overall average order value. 
SELECT
r.restaurant_name,
ROUND(AVG(o.order_amount), 2) AS average_order_value
FROM restaurants AS r
INNER JOIN orders AS o
ON r.restaurant_id = o.restaurant_id
GROUP BY
r.restaurant_id,
r.restaurant_name
HAVING AVG(o.order_amount) > (
SELECT AVG(order_amount)
FROM orders
);

-- 7.  Find customers who have never placed any orders. 
SELECT
c.customer_id,
c.customer_name
FROM customers c
LEFT JOIN orders o
ON c.customer_id = o.customer_id
WHERE o.order_id IS NULL;

-- 8.  Show the top 5 customers based on total spending. 
SELECT
c.customer_id,
c.customer_name,
SUM(o.order_amount) AS total_spending
FROM customers AS c
INNER JOIN orders AS o
ON c.customer_id = o.customer_id
GROUP BY
c.customer_id,
c.customer_name
ORDER BY total_spending DESC
LIMIT 5;

-- 9.  Find the most frequently used payment method. 
SELECT
payment_method,
COUNT(*) AS total_transactions
FROM orders
GROUP BY payment_method
ORDER BY total_transactions DESC
LIMIT 1;

-- 10.  Calculate the running total of revenue by order date. 
SELECT
order_date,
SUM(order_amount) AS daily_revenue,
SUM(SUM(order_amount)) OVER (
ORDER BY order_date) 
AS running_total_revenue
FROM orders
GROUP BY order_date
ORDER BY order_date;

-- 11.  Rank restaurants based on total revenue generated. 
SELECT
r.restaurant_name,
SUM(o.order_amount) AS total_revenue,
RANK() OVER (
ORDER BY SUM(o.order_amount) DESC
) 
AS revenue_rank
FROM restaurants AS r
INNER JOIN orders AS o
ON r.restaurant_id = o.restaurant_id
GROUP BY
r.restaurant_id,
r.restaurant_name
ORDER BY revenue_rank;

-- 12.  Find the second highest order amount from the orders table. 
SELECT MAX(order_amount) AS second_highest_order_amount
FROM orders
WHERE order_amount < (
SELECT MAX(order_amount)
FROM orders
);

-- 13.  Find customers who placed more orders than the average number of orders per customer. 
SELECT
c.customer_id,
c.customer_name,
COUNT(o.order_id) AS total_orders
FROM customers AS c
INNER JOIN orders AS o
ON c.customer_id = o.customer_id
GROUP BY
c.customer_id,
c.customer_name
HAVING COUNT(o.order_id) > (
SELECT AVG(order_count)
FROM (
SELECT COUNT(order_id) AS order_count
FROM orders
GROUP BY customer_id
) AS customer_orders
)
ORDER BY total_orders DESC;



-- 14.  Display the top 3 restaurants in each city based on total orders received. 
USE restaurant_projects;
WITH RestaurantOrders AS (
SELECT
r.city,
r.restaurant_id,
r.restaurant_name,
COUNT(o.order_id) AS total_orders
FROM restaurants AS r
LEFT JOIN orders AS o
ON r.restaurant_id = o.restaurant_id
GROUP BY
r.city,
r.restaurant_id,
r.restaurant_name
),
RankedRestaurants AS (
SELECT
city,
restaurant_id,
restaurant_name,
total_orders,
ROW_NUMBER() OVER (
PARTITION BY city
ORDER BY total_orders DESC, restaurant_id
) AS restaurant_rank
FROM RestaurantOrders
)
SELECT
city,
restaurant_name,
total_orders,
restaurant_rank
FROM RankedRestaurants
WHERE restaurant_rank <= 3
ORDER BY city, restaurant_rank;

-- 15.  Calculate month-wise revenue and show the previous month revenue.
WITH MonthlyRevenue AS (
SELECT
DATE_FORMAT(order_date, '%Y-%m') AS revenue_month,
SUM(order_amount) AS monthly_revenue
FROM orders
GROUP BY DATE_FORMAT(order_date, '%Y-%m')
)
SELECT
revenue_month,
monthly_revenue,
LAG(monthly_revenue) OVER (
ORDER BY revenue_month
) AS previous_month_revenue
FROM MonthlyRevenue
ORDER BY revenue_month;
